121	static void rounder_cb(lv_event_t * e)
122	{
123	    lv_nuttx_lcd_t * lcd = lv_event_get_user_data(e);
124	    lv_area_t * area = lv_event_get_param(e);
125	    struct lcddev_area_align_s * align_info = &lcd->align_info;
126	    int32_t w;
127	    int32_t h;
128	
129	    area->x1 &= ~(align_info->col_start_align - 1);
130	    area->y1 &= ~(align_info->row_start_align - 1);
131	
132	    w = align_round_up(lv_area_get_width(area), align_info->width_align);
133	    h = align_round_up(lv_area_get_height(area), align_info->height_align);
134	
135	    area->x2 = area->x1 + w - 1;
136	    area->y2 = area->y1 + h - 1;
137	}
