139	/* M4 frame-rate probe: measure the LCDDEVIO_PUTAREA ioctl duration (SPI
140	 * throughput) and periodic flush rate.  Guarded by the first-40 + every-100
141	 * log pattern so steady-state stays quiet.  Remove after M4 settles. */
142	static int s_flush_count = 0;
143	static struct timespec s_rate_t0;
144	
145	static void flush_cb(lv_display_t * disp, const lv_area_t * area_p,
146	                     uint8_t * color_p)
147	{
148	    lv_nuttx_lcd_t * lcd = disp->driver_data;
149	    int ret;
150	    struct timespec t0, t1;
151	    long us;
152	
153	    lcd->area.row_start = area_p->y1;
154	    lcd->area.row_end = area_p->y2;
155	    lcd->area.col_start = area_p->x1;
156	    lcd->area.col_end = area_p->x2;
157	    lcd->area.data = (uint8_t *)color_p;
158	
159	    clock_gettime(CLOCK_MONOTONIC, &t0);
160	    ret = ioctl(lcd->fd, LCDDEVIO_PUTAREA, (unsigned long) & (lcd->area));
161	    clock_gettime(CLOCK_MONOTONIC, &t1);
162	
163	    us = (t1.tv_sec - t0.tv_sec) * 1000000 + (t1.tv_nsec - t0.tv_nsec) / 1000;
164	
165	    if (s_flush_count == 0)
166	      s_rate_t0 = t0;
167	
168	    if (s_flush_count < 40 || ret < 0)
169	      {
170	        int w = area_p->x2 - area_p->x1 + 1;
171	        int h = area_p->y2 - area_p->y1 + 1;
172	        /* (w*h*2) bytes / us = bytes per microsecond = MB/s (decimal). */
173	        syslog(LOG_INFO, "[lv_nuttx_lcd] flush #%d %dx%d rc=%d %ldus"
174	               " (%ld MB/s)\n", ++s_flush_count, w, h, ret, us,
175	               us > 0 ? (long)((w * h * 2) / us) : 0);
176	      }
177	    else
178	      {
179	        s_flush_count++;
180	      }
181	
182	    /* Every 100 flushes: report the rolling flush rate. */
183	    if (s_flush_count >= 100 && (s_flush_count % 100) == 0)
184	      {
185	        long ms = (t1.tv_sec - s_rate_t0.tv_sec) * 1000
186	                + (t1.tv_nsec - s_rate_t0.tv_nsec) / 1000000;
187	        syslog(LOG_INFO, "[lv_nuttx_lcd] rate: %d flushes in %ldms"
188	               " (%.1f flush/s)\n", s_flush_count, ms,
189	               ms > 0 ? (float)s_flush_count * 1000.0f / ms : 0.0f);
190	        s_rate_t0 = t1;
191	      }
192	
193	    lv_display_flush_ready(disp);
194	}
