203	        LV_LOG_ERROR("lv_nuttx_lcd_t malloc failed");
204	        return NULL;
205	    }
206	
207	    lv_display_t * disp = lv_display_create(hor_res, ver_res);
208	    if(disp == NULL) {
209	        lv_free(lcd);
210	        return NULL;
211	    }
212	
213	    uint32_t px_size = lv_color_format_get_size(lv_display_get_color_format(disp));
214	#if LV_NUTTX_LCD_BUFFER_COUNT > 0
215	    uint32_t buf_size = hor_res * ver_res * px_size;
216	    lv_display_render_mode_t render_mode = LV_DISPLAY_RENDER_MODE_FULL;
217	#else
218	    uint32_t buf_size = hor_res * LV_NUTTX_LCD_BUFFER_SIZE * px_size;
219	    lv_display_render_mode_t render_mode = LV_DISPLAY_RENDER_MODE_PARTIAL;
220	#endif
