223	    if(draw_buf == NULL) {
224	        LV_LOG_ERROR("display draw_buf malloc failed");
225	        lv_free(lcd);
226	        return NULL;
227	    }
228	
229	#if LV_NUTTX_LCD_BUFFER_COUNT == 2
230	    draw_buf_2 = lv_malloc(buf_size);
231	    if(draw_buf_2 == NULL) {
232	        LV_LOG_ERROR("display draw_buf_2 malloc failed");
233	        lv_free(lcd);
234	        lv_free(draw_buf);
235	        return NULL;
236	    }
237	#endif
238	
239	    lcd->fd = fd;
240	    if(ioctl(fd, LCDDEVIO_GETAREAALIGN, &lcd->align_info) < 0) {
241	        perror("Error: ioctl(LCDDEVIO_GETAREAALIGN) failed");
242	    }
243	
244	    lcd->disp = disp;
245	    lv_display_set_buffers(lcd->disp, draw_buf, draw_buf_2, buf_size, render_mode);
246	    lv_display_set_flush_cb(lcd->disp, flush_cb);
247	    lv_display_add_event_cb(lcd->disp, rounder_cb, LV_EVENT_INVALIDATE_AREA, lcd);
248	    lv_display_add_event_cb(lcd->disp, display_release_cb, LV_EVENT_DELETE, lcd->disp);
249	    lv_display_set_driver_data(lcd->disp, lcd);
250	
251	    return lcd->disp;
252	}
