134	static const struct pet_frames_s *s_frames = &s_frames_by_type[PET_TYPE_CAT];
135	
136	/* ---------- animation exec callbacks (LVGL v9: (obj, value)) ---------- */
137	
138	/* LVGL v9 exec_cb signature is lv_anim_exec_xcb_t = void(*)(void*, lv_anim_value_t),
139	 * i.e. the first arg is the animated var (void*), NOT lv_obj_t* nor lv_anim_t*.
140	 * We cast to lv_obj_t* inside for the lv_obj and lv_arc calls. */
141	/* Spinner: a 90° segment rotating (THINKING / LISTENING). value = start angle. */
142	static void spin_cb(void *obj, int32_t v)
143	{
144	  lv_obj_t *o = (lv_obj_t *)obj;
145	  lv_arc_set_angles(o, v, v + 90);
146	}
147	
148	/* Growing fill: indicator grows 0→360 (EXECUTING). value = end angle. */
149	static void fill_cb(void *obj, int32_t v)
150	{
151	  lv_obj_t *o = (lv_obj_t *)obj;
152	  lv_arc_set_angles(o, 0, v);
153	}
154	
155	/* Breathing: sprite opacity pulses (IDLE). value 0..100. */
156	static void breathe_cb(void *obj, int32_t v)
157	{
158	  lv_obj_t *o = (lv_obj_t *)obj;
159	  /* 100% → 255, 0% → 190 (gentle). */
160	  lv_obj_set_style_opa(o, LV_OPA_COVER - (v * (LV_OPA_COVER - 190)) / 100, 0);
161	}
162	
163	/* Float: gentle vertical bob (IDLE, layered with the opacity breathe so the
164	 * idle pet feels alive rather than a static icon). value 0..100. */
165	static void float_cb(void *obj, int32_t v)
166	{
167	  lv_obj_t *o = (lv_obj_t *)obj;
168	  /* Triangle 0→+2→0→-2→0 across one cycle — a ±2px bob on a 96px sprite. */
169	  int32_t amp;
170	  if (v < 25)      amp = (v * 2) / 25;
171	  else if (v < 50) amp = ((50 - v) * 2) / 25;
172	  else if (v < 75) amp = -((v - 50) * 2) / 25;
173	  else             amp = -((100 - v) * 2) / 25;
174	  lv_obj_set_style_translate_y(o, amp, 0);
175	}
176	
177	/* Blink: swap between open/closed eyes (WAITING). value 0..100, closed at mid. */
178	static void blink_cb(void *obj, int32_t v)
179	{
180	  lv_obj_t *o = (lv_obj_t *)obj;
181	  /* open → closed(35..65) → open.  Two-frame swap reads as a pixel blink. */
182	  lv_image_set_src(o, (v >= 35 && v <= 65) ? s_frames->blink
183	                                            : s_frames->base);
184	}
185	
186	/* Shake: sprite x jitter (ERROR). value 0..100 maps to a few oscillations. */
187	static void shake_cb(void *obj, int32_t v)
188	{
189	  lv_obj_t *o = (lv_obj_t *)obj;
190	  /* 0..100 → four half-swings of ±5px. Simple triangle per 25-step. */
191	  int seg = v / 25;
192	  int phase = v % 25;
193	  int amp = (phase < 13) ? (phase * 5 / 12) : ((25 - phase) * 5 / 12);
194	  int sign = (seg % 2 == 0) ? 1 : -1;
195	  lv_obj_set_style_translate_x(o, sign * amp, 0);
196	}
197	
198	static void stop_anim(void)
199	{
200	  /* Delete any anim bound to our widgets. lv_anim_delete is a no-op if none. */
201	  if (s_pet.ring)   lv_anim_delete(s_pet.ring,   spin_cb);
202	  if (s_pet.sprite) lv_anim_delete(s_pet.sprite, breathe_cb);
203	  if (s_pet.sprite) lv_anim_delete(s_pet.sprite, shake_cb);
204	  if (s_pet.sprite) lv_anim_delete(s_pet.sprite, blink_cb);
205	  if (s_pet.sprite) lv_anim_delete(s_pet.sprite, float_cb);
206	  s_pet.anim_active = false;
207	}
208	
209	/* Per-state face: each agent state shows a distinct expression (eyes-only edits
210	 * on the CC0 base face — see gen_pet_expressions.py).  WAITING returns the
211	 * open-eye base because its blink anim swaps base↔blink itself. */
212	static const lv_image_dsc_t *sprite_for(enum pet_state st)
213	{
214	  switch (st)
215	    {
216	      case PET_STATE_LISTENING: return s_frames->eyes_down;
217	      case PET_STATE_THINKING:  return s_frames->eyes_up;
218	      case PET_STATE_EXECUTING: return s_frames->focused;
219	      case PET_STATE_ERROR:     return s_frames->error;
220	      case PET_STATE_WAITING:
221	      case PET_STATE_IDLE:
222	      default:                  return s_frames->base;
223	    }
224	}
225	
226	static void start_anim_for(enum pet_state st)
227	{
228	  lv_anim_t a;
229	  uint32_t color = s_state_color[st];
230	
231	  stop_anim();
232	  if (!s_pet.ring || !s_pet.sprite) return;
233	
234	  /* Indicator color always tracks state (the dark track stays constant);
235	   * base angles reset per effect. */
236	  lv_obj_set_style_arc_color(s_pet.ring, lv_color_hex(color), LV_PART_INDICATOR);
237	
238	  /* Face tracks state too — each state's expression frame (blink anim swaps it). */
239	  lv_image_set_src(s_pet.sprite, sprite_for(st));
240	
241	  switch (st)
242	    {
243	      case PET_STATE_THINKING:
244	      case PET_STATE_LISTENING:
245	        lv_anim_init(&a);
246	        lv_anim_set_var(&a, s_pet.ring);
247	        lv_anim_set_values(&a, 0, 360);
248	        lv_anim_set_time(&a, 1400);
249	        lv_anim_set_exec_cb(&a, spin_cb);
250	        lv_anim_set_repeat_count(&a, LV_ANIM_REPEAT_INFINITE);
251	        lv_anim_start(&a);
252	        break;
253	      case PET_STATE_EXECUTING:
254	        lv_anim_init(&a);
255	        lv_anim_set_var(&a, s_pet.ring);
256	        lv_anim_set_values(&a, 0, 360);
257	        lv_anim_set_time(&a, 900);
258	        lv_anim_set_exec_cb(&a, fill_cb);
259	        lv_anim_set_repeat_count(&a, LV_ANIM_REPEAT_INFINITE);
260	        lv_anim_start(&a);
261	        break;
262	      case PET_STATE_IDLE:
263	        lv_anim_init(&a);
264	        lv_anim_set_var(&a, s_pet.sprite);
265	        lv_anim_set_values(&a, 0, 100);
266	        lv_anim_set_time(&a, 1800);
267	        lv_anim_set_exec_cb(&a, breathe_cb);
268	        lv_anim_set_repeat_count(&a, LV_ANIM_REPEAT_INFINITE);
269	        lv_anim_start(&a);
270	        /* Layered float: a slow bob on a distinct period so the two effects
271	         * don't phase-lock.  lv_anim_start copies `a`, so it is safe to reuse
272	         * the same local descriptor for a second anim. */
273	        lv_anim_init(&a);
274	        lv_anim_set_var(&a, s_pet.sprite);
275	        lv_anim_set_values(&a, 0, 100);
276	        lv_anim_set_time(&a, 2600);
277	        lv_anim_set_exec_cb(&a, float_cb);
278	        lv_anim_set_repeat_count(&a, LV_ANIM_REPEAT_INFINITE);
279	        lv_anim_start(&a);
280	        lv_arc_set_angles(s_pet.ring, 0, 360);  /* full ring */
281	        break;
282	      case PET_STATE_WAITING:
283	        lv_anim_init(&a);
284	        lv_anim_set_var(&a, s_pet.sprite);
285	        lv_anim_set_values(&a, 0, 100);
286	        lv_anim_set_time(&a, 900);
287	        lv_anim_set_exec_cb(&a, blink_cb);
288	        lv_anim_set_repeat_count(&a, LV_ANIM_REPEAT_INFINITE);
289	        lv_anim_start(&a);
290	        lv_arc_set_angles(s_pet.ring, 0, 360);
291	        break;
292	      case PET_STATE_ERROR:
293	        lv_anim_init(&a);
294	        lv_anim_set_var(&a, s_pet.sprite);
295	        lv_anim_set_values(&a, 0, 100);
296	        lv_anim_set_time(&a, 350);
297	        lv_anim_set_exec_cb(&a, shake_cb);
298	        lv_anim_set_repeat_count(&a, LV_ANIM_REPEAT_INFINITE);
299	        lv_anim_start(&a);
300	        lv_arc_set_angles(s_pet.ring, 0, 360);
301	        break;
302	      default:
303	        lv_arc_set_angles(s_pet.ring, 0, 360);
304	        break;
305	    }
306	  s_pet.anim_active = true;
307	}
308	
309	/* ---------- async apply (runs in LVGL thread) ---------- */
310	
311	static void apply_state_async_cb(void *data)
312	{
313	  enum pet_state st = (enum pet_state)(intptr_t)data;
314	  if (!s_pet.initialized || !s_pet.sprite) return;
315	
316	  s_pet.state = st;
317	
318	  /* Reset the sprite to a clean base frame; per-state anim re-derives it. */
319	  lv_image_set_src(s_pet.sprite, s_frames->base);
320	  lv_obj_set_style_translate_x(s_pet.sprite, 0, 0);  /* clear any shake offset */
321	  lv_obj_set_style_translate_y(s_pet.sprite, 0, 0);  /* clear any float offset */
322	  lv_obj_set_style_opa(s_pet.sprite, LV_OPA_COVER, 0);
323	
324	  if (s_pet.label) lv_label_set_text(s_pet.label, s_state_text[st]);
325	  if (s_pet.status_dot) {
326	    lv_obj_set_style_bg_color(s_pet.status_dot, lv_color_hex(s_state_color[st]), 0);
327	  }
328	
329	  start_anim_for(st);
330	  syslog(LOG_INFO, "[%s] state → %s\n", TAG, s_state_text[st]);
331	}
332	
333	void pet_status_view_set_state(enum pet_state state)
334	{
335	  if ((int)state < 0 || (int)state > PET_STATE_ERROR) return;
336	  /* Async: widget mutation must happen in the LVGL thread. */
337	  lv_async_call(apply_state_async_cb, (void *)(intptr_t)state);
338	}
339	
340	static void apply_type_async_cb(void *data)
341	{
342	  enum pet_type type = (enum pet_type)(intptr_t)data;
343	  if (!s_pet.initialized || !s_pet.sprite) return;
344	
345	  s_pet.type = type;
346	  s_frames = &s_frames_by_type[type];
347	
348	  /* Re-derive the current state's expression under the new sprite sheet and
349	   * restart its anim (blink_cb reads s_frames, so it picks up the swap too). */
350	  lv_image_set_src(s_pet.sprite, s_frames->base);
351	  lv_obj_set_style_translate_x(s_pet.sprite, 0, 0);
352	  lv_obj_set_style_translate_y(s_pet.sprite, 0, 0);
353	  lv_obj_set_style_opa(s_pet.sprite, LV_OPA_COVER, 0);
354	
355	  start_anim_for(s_pet.state);
356	  syslog(LOG_INFO, "[%s] type → %d\n", TAG, (int)type);
357	}
358	
359	void pet_status_view_set_type(int type)
360	{
361	  if (type < 0 || type >= PET_TYPE_COUNT) type = PET_TYPE_CAT;
362	  lv_async_call(apply_type_async_cb, (void *)(intptr_t)type);
363	}
364	
365	/* ---------- screen show / hide ---------- */
366	
367	static void show_async_cb(void *data)
368	{
369	  (void)data;
370	  if (!s_pet.initialized || !s_pet.screen || s_pet.visible) return;
371	  s_pet.prev_screen = lv_screen_active();
372	  lv_screen_load_anim(s_pet.screen, LV_SCR_LOAD_ANIM_FADE_IN,
373	                      SCREEN_FADE_MS, 0, false);
374	  /* lv_screen_load already invalidates the full screen and schedules a redraw;
375	   * the explicit invalidate + lv_refr_now below was a qemu-goldfish-headless
376	   * lazy-flush workaround that is unnecessary on the real CP /dev/lcd0 panel,
377	   * where it caused a full-frame (top-to-bottom) white flicker on every idle
378	   * pet↔particle rotate.  Real hardware renders screen switches fine without
379	   * the extra synchronous refresh, so we drop it to stop the standby flicker. */
380	  s_pet.visible = true;
381	  /* Re-assert current state's animation (lv_anim may have been paused off-screen). */
382	  start_anim_for(s_pet.state);
383	  syslog(LOG_INFO, "[%s] pet screen shown\n", TAG);
384	}
385	
386	void pet_status_view_show(void)
387	{
388	  if (!s_pet.initialized) return;
389	  lv_async_call(show_async_cb, NULL);
390	}
391	
392	static void hide_async_cb(void *data)
393	{
394	  (void)data;
395	  if (!s_pet.initialized || !s_pet.visible) return;
396	  stop_anim();
397	  if (s_pet.prev_screen)
398	    lv_screen_load_anim(s_pet.prev_screen, LV_SCR_LOAD_ANIM_FADE_IN,
399	                        SCREEN_FADE_MS, 0, false);
400	  s_pet.visible = false;
401	  syslog(LOG_INFO, "[%s] pet screen hidden\n", TAG);
402	}
403	
404	void pet_status_view_hide(void)
405	{
406	  if (!s_pet.initialized) return;
407	  lv_async_call(hide_async_cb, NULL);
408	}
409	
410	bool pet_status_view_is_visible(void)
411	{
412	  return s_pet.visible;
413	}
