415	/* ---------- init ---------- */
416	
417	int pet_status_view_init(void)
418	{
419	  if (s_pet.initialized) return 0;
420	
421	  memset(&s_pet, 0, sizeof(s_pet));
422	  s_pet.state = PET_STATE_IDLE;
423	  s_pet.type = PET_TYPE_CAT;
424	  s_frames = &s_frames_by_type[PET_TYPE_CAT];
425	
426	  s_pet.screen = lv_obj_create(NULL);
427	  if (!s_pet.screen) return -ENOMEM;
428	  lv_obj_set_style_bg_color(s_pet.screen, lv_color_hex(UI_PAL_BG), 0);
429	  lv_obj_set_style_bg_opa(s_pet.screen, LV_OPA_COVER, 0);
430	  lv_obj_set_style_text_font(s_pet.screen, &lv_font_misans_16_cjk, 0);
431	
432	  /* Ring (arc) — centered, subtle dark track, state-colored indicator. */
433	  s_pet.ring = lv_arc_create(s_pet.screen);
434	  if (s_pet.ring)
435	    {
436	      lv_obj_set_size(s_pet.ring, PET_RING_SIZE, PET_RING_SIZE);
437	      lv_obj_center(s_pet.ring);
438	      lv_arc_set_rotation(s_pet.ring, 0);
439	      lv_arc_set_bg_angles(s_pet.ring, 0, 360);
440	      lv_arc_set_angles(s_pet.ring, 0, 360);
441	      lv_arc_set_range(s_pet.ring, 0, 360);
442	      /* Track (LV_PART_MAIN): a subtle dark full circle that stays put. */
443	      lv_obj_set_style_arc_width(s_pet.ring, 4, LV_PART_MAIN);
444	      lv_obj_set_style_arc_color(s_pet.ring, lv_color_hex(UI_PAL_TRACK), LV_PART_MAIN);
445	      lv_obj_set_style_arc_rounded(s_pet.ring, true, LV_PART_MAIN);
446	      /* Indicator (LV_PART_INDICATOR): the state-colored spinner / fill.
447	       * (Previously only LV_PART_MAIN was styled, so the animated segment fell
448	       * back to the theme's default blue arc — the "ugly" ring.) */
449	      lv_obj_set_style_arc_width(s_pet.ring, 4, LV_PART_INDICATOR);
450	      lv_obj_set_style_arc_color(s_pet.ring, lv_color_hex(UI_PAL_IDLE), LV_PART_INDICATOR);
451	      lv_obj_set_style_arc_rounded(s_pet.ring, true, LV_PART_INDICATOR);
452	      lv_obj_remove_flag(s_pet.ring, LV_OBJ_FLAG_CLICKABLE);
453	      /* Hide the arc knob. */
454	      lv_obj_set_style_bg_opa(s_pet.ring, LV_OPA_TRANSP, LV_PART_KNOB);
455	    }
456	
457	  /* Pixel pet — CC0 sprite scaled 6x (nearest-neighbor for crisp pixels). */
458	  s_pet.sprite = lv_image_create(s_pet.screen);
459	  if (!s_pet.sprite) goto fail;
460	  lv_image_set_src(s_pet.sprite, s_frames->base);
461	  lv_image_set_antialias(s_pet.sprite, false);
462	  lv_image_set_scale(s_pet.sprite, PET_SPRITE_SCALE * 256);
463	  lv_obj_center(s_pet.sprite);
464	
465	  /* Status caption row below the sprite: a colored status dot (HachimoDock
466	   * circular status marker) + the state text, laid out horizontally. */
467	  {
468	    lv_obj_t *caption = lv_obj_create(s_pet.screen);
469	    if (!caption) goto fail;
470	    lv_obj_remove_flag(caption, LV_OBJ_FLAG_SCROLLABLE);
471	    lv_obj_set_size(caption, LV_SIZE_CONTENT, LV_SIZE_CONTENT);
472	    lv_obj_set_style_bg_opa(caption, LV_OPA_TRANSP, 0);
473	    lv_obj_set_style_border_width(caption, 0, 0);
474	    lv_obj_set_style_pad_all(caption, 0, 0);
475	    lv_obj_set_flex_flow(caption, LV_FLEX_FLOW_ROW);
