57	#define CORE_DIAM      34
58	#define GUIDE_RING_DIAM 150
59	#define VEL_Q           8        /* velocity fixed-point: 256 = 1 px/tick */
60	#define ONE_PX          (1 << VEL_Q)
61	#define TICK_MS         33
