63	/* State palette — HachimoDock 柔和低饱和状态色，语义同 pet_status_view。 */
64	static const uint32_t s_state_color[] = {
65	  UI_PAL_IDLE, UI_PAL_LISTEN, UI_PAL_THINK, UI_PAL_EXEC, UI_PAL_WAIT, UI_PAL_ERROR,
66	};
