68	  /* Mirrors pet_status_view's captions — and, critically, sticks to glyphs
69	   * present in the CP MiSans 16 subset (the old "粒子·" prefix used 粒/子,
70	   * which are NOT in the trimmed CP font and rendered as tofu on-device). */
71	  "待机", "聆听中", "思考中", "执行中", "等待确认", "出错了",
72	};
