74	/* Per-state physics knobs:
75	 *   perturb  — LCG noise amplitude fed into velocity (q8 units)
76	 *   swirl    — tangential bias strength (rotation; +CW, -CCW)
77	 *   radial   — radial bias (+outward / -inward)
78	 *   damp     — velocity retention per tick (0..256) */
79	typedef struct {
80	  int32_t perturb;
81	  int32_t swirl;
82	  int32_t radial;
83	  int32_t damp;
84	} phys_t;
85	
86	static const phys_t s_phys[] = {
87	  [PARTICLE_STATE_IDLE]      = { 10,   4,   0, 248 },  /* gentle drift */
88	  [PARTICLE_STATE_LISTENING] = { 16,  10, -18, 244 },  /* inward + slow swirl */
89	  [PARTICLE_STATE_THINKING] = { 20,  34,   0, 250 },  /* fast swirl */
90	  [PARTICLE_STATE_EXECUTING] = { 28,  -8,  26, 246 }, /* outward burst */
91	  [PARTICLE_STATE_WAITING]   = {  4,   2,   0, 220 },  /* near-frozen pulse */
92	  [PARTICLE_STATE_ERROR]     = { 90,   0,   0, 252 },  /* chaotic scatter */
93	};
94	
95	struct particle_s {
96	  int32_t x, y;          /* position, pixels */
97	  int32_t vx, vy;        /* velocity, q8 (256 = 1px/tick) */
98	  uint32_t lcg;          /* per-particle pseudo-noise state */
99	  int32_t last_rx, last_ry;  /* last rendered top-left; skip set_pos if unchanged */
100	};
101	
102	struct pf_state_s {
103	  bool initialized;
104	  bool visible;
105	  enum particle_state state;
106	  lv_obj_t *screen;
107	  lv_obj_t *guide_ring;  /* faint lv_arc, shared motif with pet */
108	  lv_obj_t *core;        /* central pulsing circle */
109	  lv_obj_t *particles[N_PARTICLES];
110	  lv_obj_t *label;
111	  lv_obj_t *status_dot;  /* colored dot paired with the state caption */
112	  lv_obj_t *prev_screen;
113	  struct particle_s p[N_PARTICLES];
114	  lv_timer_t *timer;
115	  uint32_t tick;
116	  /* display geometry (pixels) */
117	  int32_t cx, cy, R, R_sq;
118	};
119	
120	static struct pf_state_s s_pf;
121	
122	/* ---------- LCG (per-particle deterministic pseudo-noise) ---------- */
123	
124	static inline int32_t lcg_next(uint32_t *s)
125	{
126	  *s = (*s * 1103515765u + 12345u) & 0x7fffffffu;
127	  return (int32_t)(*s >> 15) - 16384;   /* [-16384, 16383] */
128	}
129	
130	/* ---------- physics step (runs in LVGL thread via timer) ---------- */
131	
132	static void physics_step(void)
133	{
134	  const phys_t *ph = &s_phys[s_pf.state];
135	  int32_t cx = s_pf.cx, cy = s_pf.cy, R_sq = s_pf.R_sq;
136	  int32_t damp = ph->damp;
137	  int32_t perturb = ph->perturb;
138	  int32_t swirl = ph->swirl;
139	  int32_t radial = ph->radial;
140	
141	  for (int i = 0; i < N_PARTICLES; i++)
142	    {
143	      struct particle_s *p = &s_pf.p[i];
144	      int32_t dx = p->x - cx;
145	      int32_t dy = p->y - cy;
146	
147	      /* LCG noise → small velocity kick (perturb in q8; noise normalized to ~[-1,1] px). */
148	      int32_t nx = lcg_next(&p->lcg);
149	      int32_t ny = lcg_next(&p->lcg);
150	      p->vx += (nx * perturb) / 16384;
151	      p->vy += (ny * perturb) / 16384;
152	
153	      /* Swirl: tangential bias ∝ radial offset (unnormalized → faster swirl
154	       * farther out, reads as rotation). tang = (-dy, dx). */
155	      p->vx += (-dy * swirl) / 64;
156	      p->vy += ( dx * swirl) / 64;
157	
158	      /* Radial bias: outward (+) pulls particles to the rim, inward (-) sucks
159	       * them toward the core. */
160	      p->vx += (dx * radial) / 64;
161	      p->vy += (dy * radial) / 64;
162	
163	      /* Damping. */
164	      p->vx = (p->vx * damp) / 256;
165	      p->vy = (p->vy * damp) / 256;
166	
167	      /* Speed clamp so chaos stays bounded. */
168	      int32_t vmax = 3 * ONE_PX;
169	      if (p->vx >  vmax) p->vx =  vmax;
170	      if (p->vx < -vmax) p->vx = -vmax;
171	      if (p->vy >  vmax) p->vy =  vmax;
172	      if (p->vy < -vmax) p->vy = -vmax;
173	
174	      /* Advance. */
175	      int32_t nxp = p->x + (p->vx >> VEL_Q);
176	      int32_t nyp = p->y + (p->vy >> VEL_Q);
177	
178	      /* Round-bound bounce: if next step leaves the disc, reverse velocity
179	       * (cheap reflection) and don't move this tick. dist_sq in pixel units
180	       * fits in int32 (max ~217k). */
181	      int32_t ddx = nxp - cx;
182	      int32_t ddy = nyp - cy;
183	      int32_t dsq = ddx * ddx + ddy * ddy;
184	      if (dsq > R_sq)
185	        {
186	          p->vx = -p->vx;
187	          p->vy = -p->vy;
188	        }
189	      else
190	        {
191	          p->x = nxp;
192	          p->y = nyp;
193	        }
194	
195	      /* Render — only invalidate when the integer pixel position actually
196	       * changes.  Particles move sub-pixel most ticks (q8 velocity), so an
197	       * unconditional set_pos would invalidate 18 regions every 33 ms even
198	       * when nothing visibly moved.  On flush paths that can't keep up
199	       * (qemu goldfish headless fb) the constant re-invalidation starves the
200	       * flush so the screen never reaches the framebuffer.  Skipping no-op
201	       * moves collapses invalidations to only real pixel crossings. */
202	      lv_obj_t *o = s_pf.particles[i];
203	      if (o)
204	        {
205	          int32_t rx = p->x - (PARTICLE_DIAM / 2);
206	          int32_t ry = p->y - (PARTICLE_DIAM / 2);
207	          if (rx != p->last_rx || ry != p->last_ry)
208	            {
209	              lv_obj_set_pos(o, rx, ry);
210	              p->last_rx = rx;
211	              p->last_ry = ry;
212	            }
213	        }
214	    }
215	
216	  /* Core pulse: opacity breathing driven by tick (no lv_anim to keep the
217	   * pulsing phase-locked to the physics tick). */
218	  if (s_pf.core)
219	    {
220	      uint32_t t = s_pf.tick & 63;            /* 0..63 */
221	      int32_t tri = (t < 32) ? t : (63 - t);  /* triangle 0..31 */
222	      lv_opa_t opa = LV_OPA_60 + (tri * (LV_OPA_COVER - LV_OPA_60)) / 31;
223	      lv_obj_set_style_opa(s_pf.core, opa, 0);
224	    }
225	
226	  s_pf.tick++;
227	}
