709	/* Async callback: load screen inside LVGL thread context */
710	static void show_screen_async_cb(void* data)
711	{
712	    (void)data;
713	    if (!s_state.initialized || !s_state.running || !s_state.screen) {
714	        return;
715	    }
716	    if (s_state.screen_visible) {
717	        return;
718	    }
719	
720	    /* CJK font selection happens at init() time via the statically-compiled
721	     * lv_font_misans_16_cjk (preferred: 3755 GB2312-1 common chars, baked into
722	     * the binary by lv_font_conv — zero runtime malloc, zero rasterization,
723	     * cannot corrupt the heap).  No runtime TTF loading here.
724	     *
725	     * History: we previously used lv_tiny_ttf_create_data() with a runtime
726	     * MiSans TTF, but stb_truetype's MakeGlyphBitmap write path overran its
727	     * output buffer on certain CJK glyphs and corrupted adjacent NuttX mm heap
728	     * chunk metadata, leading to recursive-assert reboots (mm_foreach /
729	     * nxsched_add_readytorun / nxsem_post_slow in the timer IRQ).  Subsetting
730	     * to 857 KB only delayed the crash; the root cause is the rasterizer, so
731	     * we moved to a pre-rasterized static font.  See lv_font_misans_16_cjk.c
732	     * and the fontgen notes in docs. */
733	    /* Already set in init(); nothing to do at show time. */
734	    syslog(LOG_INFO, "[%s] using static MiSans-16 CJK font\n", TAG);
735	
736	    syslog(LOG_INFO, "[%s] loading chat screen\n", TAG);
737	
738	    /* Save the current screen so we can restore it on stop.
739	     * The launcher (miwear) owns this screen — we must not delete it. */
740	    s_state.prev_screen = lv_screen_active();
741	
742	    lv_screen_load_anim(s_state.screen, LV_SCR_LOAD_ANIM_FADE_IN,
