750	    syslog(LOG_INFO, "[%s] CARD_SELFTEST: injecting sample cards\n", TAG);
751	    chat_view_add_message("这个提交已 MERGED,状态: 正常合入", false, 0);
752	    chat_view_add_message("Jira issue FEEDBACK-149182,经办人: 张文海,More Info", false, 0);
753	    chat_view_add_message("值得合入,建议采纳,yes", false, 0);
