775	int lvgl_ui_channel_send(const char* text)
776	{
777	    int ret;
778	    async_msg_t* payload;
779	
780	    /* Parameter validation: NULL or empty string */
781	    if (!text || text[0] == '\0') {
782	        syslog(LOG_ERR, "[%s] send: invalid text (NULL or empty)\n", TAG);
783	        return -EINVAL;
784	    }
785	
786	    /* Check channel readiness */
787	    if (!s_state.initialized || !s_state.running) {
788	        syslog(LOG_ERR, "[%s] send: channel not ready (init=%d run=%d)\n",
789	            TAG, s_state.initialized, s_state.running);
790	        return -EINVAL;
791	    }
792	
793	    /* Auto-show chat screen on first Agent reply */
794	    if (!s_state.screen_visible) {
795	        lvgl_ui_channel_show();
796	    }
797	
798	    /* Schedule bubble creation in LVGL thread via lv_async_call.
799	     * This avoids the "Invalidate area is not allowed during rendering"
800	     * assertion crash that occurs when we create LVGL widgets from
801	     * the agent dispatch thread while miwear's LVGL thread is
802	     * mid-render. */
803	    payload = malloc(sizeof(async_msg_t));
804	    if (!payload) {
805	        syslog(LOG_ERR, "[%s] send: async payload alloc failed\n", TAG);
806	        return -ENOMEM;
807	    }
808	
809	    chat_view_copy_text(payload->text, text, LVGL_UI_MSG_MAX_LEN);
810	    payload->is_user = false;
811	
812	    lv_async_call(chat_view_add_message_async_cb, payload);
813	
814	    /* TTS is blocking — run after scheduling the UI update */
815	    ret = voice_channel_speak(text);
816	    if (ret != 0) {
817	        syslog(LOG_ERR, "[%s] voice_channel_speak failed (rc=%d)\n", TAG, ret);
818	    }
819	
820	    return 0;
821	}
