915	#endif
916	        break;
917	    case LVGL_UI_PTT_PROCESSING:
918	        s_state.is_recording = false;
919	        s_state.is_processing = true;
920	#ifdef CONFIG_AI_AGENT_PET_STATUS
921	        pet_status_view_set_state(PET_STATE_THINKING);
922	#endif
923	        break;
924	    case LVGL_UI_PTT_IDLE:
925	    default:
926	        s_state.is_recording = false;
927	        s_state.is_processing = false;
928	#ifdef CONFIG_AI_AGENT_PET_STATUS
929	        pet_status_view_set_state(PET_STATE_IDLE);
930	#endif
931	        break;
932	    }
