/*
 * standby_view.c — 待机数字时钟(长时间无操作后自动进入的暗色息屏界面)。
 * ...
 */

#include <nuttx/config.h>
#ifdef CONFIG_AI_AGENT_STANDBY_UI

#include "ui/standby_view.h"
#include "ui/ui_palette.h"

#include <stdbool.h>
#include <string.h>
#include <syslog.h>
#include <time.h>

#include <lvgl/lvgl.h>

#define TAG "standby_view"

#define SCREEN_FADE_MS 500

LV_FONT_DECLARE(lv_font_misans_16_cjk);

/* Dim clock colors — deliberately darker than the normal UI_PAL_TEXT_DIM so the
 * standby reads as "off". */
#define CLOCK_COLOR 0x4A4F4D
#define DATE_COLOR  0x363A38
#define HINT_COLOR  0x2A2D2B

static const char *const s_weekday[] = {
  "周日", "周一", "周二", "周三", "周四", "周五", "周六",
};

struct standby_s {
  bool initialized;
  bool visible;
  lv_obj_t *screen;
  lv_obj_t *clock;
  lv_obj_t *date;
  lv_obj_t *hint;
  lv_obj_t *prev_screen;
  lv_timer_t *timer;
  char last_clock[8];
  char last_date[32];
  bool anim_active;
};

static struct standby_s s_sb;

/* Slow opacity breathe on the clock so the standby looks alive, not frozen. */
static void breathe_cb(void *obj, int32_t v)
{
  lv_obj_t *o = (lv_obj_t *)obj;
  lv_obj_set_style_opa(o, LV_OPA_COVER - (v * (LV_OPA_COVER - 150)) / 100, 0);
}

static void start_breathe(void)
{
  if (!s_sb.clock || s_sb.anim_active) return;
  lv_anim_t a;
  lv_anim_init(&a);
  lv_anim_set_var(&a, s_sb.clock);
  lv_anim_set_values(&a, 0, 100);
  lv_anim_set_time(&a, 2600);
  lv_anim_set_exec_cb(&a, breathe_cb);
  lv_anim_set_repeat_count(&a, LV_ANIM_REPEAT_INFINITE);
  lv_anim_start(&a);
  s_sb.anim_active = true;
}

static void stop_breathe(void)
{
  if (!s_sb.clock) return;
  lv_anim_delete(s_sb.clock, breathe_cb);
  lv_obj_set_style_opa(s_sb.clock, LV_OPA_COVER, 0);
  s_sb.anim_active = false;
}

static void update_time(void)
{
  time_t now = time(NULL);
  struct tm tm_now;
  localtime_r(&now, &tm_now);

  char clock[8];
  snprintf(clock, sizeof(clock), "%02d:%02d", tm_now.tm_hour, tm_now.tm_min);

  char date[32];
  snprintf(date, sizeof(date), "%d月%d日 %s", tm_now.tm_mon + 1, tm_now.tm_mday,
           s_weekday[tm_now.tm_wday]);

  if (s_sb.clock && strcmp(clock, s_sb.last_clock) != 0)
    {
      lv_label_set_text(s_sb.clock, clock);
      strcpy(s_sb.last_clock, clock);
    }
  if (s_sb.date && strcmp(date, s_sb.last_date) != 0)
    {
      lv_label_set_text(s_sb.date, date);
      strcpy(s_sb.last_date, date);
    }
}

static void timer_cb(lv_timer_t *t)
{
  (void)t;
  if (s_sb.initialized && s_sb.visible)
    update_time();
}

static void show_async_cb(void *data)
{
  (void)data;
  if (!s_sb.initialized || !s_sb.screen || s_sb.visible) return;
  update_time();
  s_sb.prev_screen = lv_screen_active();
  lv_screen_load_anim(s_sb.screen, LV_SCR_LOAD_ANIM_FADE_IN, SCREEN_FADE_MS, 0, false);
  s_sb.visible = true;
  start_breathe();
  syslog(LOG_INFO, "[%s] standby clock shown\n", TAG);
}

void standby_view_show(void)
{
  if (!s_sb.initialized) return;
  lv_async_call(show_async_cb, NULL);
}

static void hide_async_cb(void *data)
{
  (void)data;
  if (!s_sb.initialized || !s_sb.visible) return;
  stop_breathe();
  if (s_sb.prev_screen)
    lv_screen_load_anim(s_sb.prev_screen, LV_SCR_LOAD_ANIM_FADE_IN, SCREEN_FADE_MS, 0, false);
  s_sb.visible = false;
  syslog(LOG_INFO, "[%s] standby clock hidden\n", TAG);
}

void standby_view_hide(void)
{
  if (!s_sb.initialized) return;
  lv_async_call(hide_async_cb, NULL);
}

bool standby_view_is_visible(void)
{
  return s_sb.visible;
}

int standby_view_init(void)
{
  if (s_sb.initialized) return 0;
  memset(&s_sb, 0, sizeof(s_sb));

  s_sb.screen = lv_obj_create(NULL);
  if (!s_sb.screen) return -ENOMEM;
  lv_obj_set_style_bg_color(s_sb.screen, lv_color_hex(UI_PAL_BG), 0);
  lv_obj_set_style_bg_opa(s_sb.screen, LV_OPA_COVER, 0);
  lv_obj_set_style_text_font(s_sb.screen, &lv_font_misans_16_cjk, 0);

  /* Big dim HH:MM clock. */
  s_sb.clock = lv_label_create(s_sb.screen);
  if (!s_sb.clock) goto fail;
  lv_label_set_text(s_sb.clock, "--:--");
  lv_obj_set_style_text_font(s_sb.clock, &lv_font_montserrat_24, 0);
  lv_obj_set_style_text_color(s_sb.clock, lv_color_hex(CLOCK_COLOR), 0);
  lv_obj_align(s_sb.clock, LV_ALIGN_CENTER, 0, -24);

  /* Date line. */
  s_sb.date = lv_label_create(s_sb.screen);
  if (!s_sb.date) goto fail;
  lv_label_set_text(s_sb.date, "");
  lv_obj_set_style_text_font(s_sb.date, &lv_font_misans_16_cjk, 0);
  lv_obj_set_style_text_color(s_sb.date, lv_color_hex(DATE_COLOR), 0);
  lv_obj_align(s_sb.date, LV_ALIGN_CENTER, 0, 12);

  /* Hint. */
  s_sb.hint = lv_label_create(s_sb.screen);
  if (!s_sb.hint) goto fail;
  lv_label_set_text(s_sb.hint, "待机中");
  lv_obj_set_style_text_font(s_sb.hint, &lv_font_misans_16_cjk, 0);
  lv_obj_set_style_text_color(s_sb.hint, lv_color_hex(HINT_COLOR), 0);
  lv_obj_align(s_sb.hint, LV_ALIGN_BOTTOM_MID, 0, -24);

  /* 1s refresh timer; the cb self-guards on visibility. */
  s_sb.timer = lv_timer_create(timer_cb, 1000, NULL);
  if (s_sb.timer)
    lv_timer_set_repeat_count(s_sb.timer, -1);

  s_sb.initialized = true;
  syslog(LOG_INFO, "[%s] init OK (暗色数字时钟待机屏)\n", TAG);
  return 0;

fail:
  if (s_sb.screen) lv_obj_del(s_sb.screen);
  memset(&s_sb, 0, sizeof(s_sb));
  return -ENOMEM;
}

#endif /* CONFIG_AI_AGENT_STANDBY_UI */
```

