661	/* Stop from an external thread (e.g. velaquit shutdown).
662	 * Schedules cleanup in the LVGL thread to avoid racing with the
663	 * miwear/launcher event loop. */
664	void lvgl_ui_channel_stop(void)
665	{
666	    /* No-op if not initialized or not running */
667	    if (!s_state.initialized || !s_state.running) {
668	        return;
669	    }
670	
671	    syslog(LOG_INFO, "[%s] stopping\n", TAG);
672	
673	    /* Mark as not running first — prevents callbacks (PTT,
674	     * chat_view_add_message) from touching widgets during teardown. */
675	    s_state.running = false;
676	
677	    /* Schedule cleanup in the LVGL thread to avoid racing with the
678	     * miwear/launcher event loop.  Direct lv_obj_del from the
679	     * shutdown thread causes a MemManage fault because the LVGL
680	     * thread may be mid-render on the same objects. */
681	    sem_init(&s_stop_sem, 0, 0);
682	    lv_async_call(stop_screen_async_cb, NULL);
683	
684	    /* Wait for LVGL thread to complete the deletion (timeout 2s) */
685	    struct timespec ts;
686	
687	    clock_gettime(CLOCK_REALTIME, &ts);
688	    ts.tv_sec += 2;
689	
690	    if (sem_timedwait(&s_stop_sem, &ts) != 0) {
691	        syslog(LOG_WARNING,
692	            "[%s] async stop timed out, forcing cleanup\n", TAG);
693	        /* Fallback: NULL out pointers without deleting (leak is
694	         * acceptable during shutdown to avoid crash). */
695	        s_state.screen = NULL;
696	        s_state.chat_list = NULL;
697	    }
698	
699	    sem_destroy(&s_stop_sem);
700	
701	    /* Destroy the mutex */
702	    pthread_mutex_destroy(&s_state.lock);
703	
704	    s_state.initialized = false;
705	
706	    syslog(LOG_INFO, "[%s] stopped\n", TAG);
707	}
