17	/*
18	 * particle_flow_view.c — 圆屏粒子流（M7 差异化页 ②，纯 LVGL）。
19	 *
20	 * 设计见 particle_flow_view.h。18 颗粒子在圆屏内做受控布朗流动，中央核心
21	 * 脉动；态切换改变粒子色 + 流向偏置（内聚 / 外散 / 旋转 / 混沌）+ 核心脉速。
22	 * 视觉与宠物脸+环刻意不同（抽象能量流），借同一套 agent 状态镜像语义。
23	 *
24	 * 物理：整数定点，位置以像素为单位，速度以 q8（256 = 1px/tick）为单位，
25	 * 每 tick (33ms≈30fps) 由 lv_timer 在 LVGL 线程推进；边界反弹用速度反转 +
26	 * 位置钳位（距离平方比较，无 sqrt）。无浮点 / math.h 依赖，跨核可移植。
27	 * 随机扰动用每粒子独立 LCG（确定性伪噪声，免 rand 依赖）。
28	 */
29	
30	#include <nuttx/config.h>
31	
32	#ifdef CONFIG_AI_AGENT_PARTICLE_FLOW
33	
34	#include "ui/particle_flow_view.h"
35	#include "ui/ui_palette.h"
36	
37	#include <stddef.h>
38	#include <stdbool.h>
39	#include <stdint.h>
40	#include <string.h>
41	#include <syslog.h>
42	#include <errno.h>
43	
44	#include <lvgl/lvgl.h>
45	
46	#define TAG "particle_view"
47	
48	/* 屏幕切换淡入时长(ms)。硬 lv_screen_load() 的整帧 SPI flush 会与面板 60Hz
49	 * GRAM 扫描竞争,表现为从上到下的白底刷屏;改用淡入交叉渐变分散到多帧,
50	 * 把刷屏变成优雅的渐隐渐显。 */
51	#define SCREEN_FADE_MS 500
52	
53	LV_FONT_DECLARE(lv_font_misans_16_cjk);
54	
55	#define N_PARTICLES    18
56	#define PARTICLE_DIAM  7        /* px, odd so center pixel is exact */
57	#define CORE_DIAM      34
58	#define GUIDE_RING_DIAM 150
59	#define VEL_Q           8        /* velocity fixed-point: 256 = 1 px/tick */
60	#define ONE_PX          (1 << VEL_Q)
61	#define TICK_MS         33
62	
63	/* State palette — HachimoDock 柔和低饱和状态色，语义同 pet_status_view。 */
64	static const uint32_t s_state_color[] = {
65	  UI_PAL_IDLE, UI_PAL_LISTEN, UI_PAL_THINK, UI_PAL_EXEC, UI_PAL_WAIT, UI_PAL_ERROR,
66	};
67	static const char *const s_state_text[] = {
68	  /* Mirrors pet_status_view's captions — and, critically, sticks to glyphs
69	   * present in the CP MiSans 16 subset (the old "粒子·" prefix used 粒/子,
70	   * which are NOT in the trimmed CP font and rendered as tofu on-device). */
71	  "待机", "聆听中", "思考中", "执行中", "等待确认", "出错了",
72	};
73	
74	/* Per-state physics knobs:
75	 *   perturb  — LCG noise amplitude fed into velocity (q8 units)
76	 *   swirl    — tangential bias strength (rotation; +CW, -CCW)
77	 *   radial   — radial bias (+outward / -inward)
78	 *   damp     — velocity retention per tick (0..256) */
79	typedef struct {
80	  int32_t perturb;
81	  int32_t swirl;
82	  int32_t radial;
83	  int32_t damp;
84	} phys_t;
85	
86	static const phys_t s_phys[] = {
87	  [PARTICLE_STATE_IDLE]      = { 10,   4,   0, 248 },  /* gentle drift */
88	  [PARTICLE_STATE_LISTENING] = { 16,  10, -18, 244 },  /* inward + slow swirl */
89	  [PARTICLE_STATE_THINKING] = { 20,  34,   0, 250 },  /* fast swirl */
90	  [PARTICLE_STATE_EXECUTING] = { 28,  -8,  26, 246 }, /* outward burst */
91	  [PARTICLE_STATE_WAITING]   = {  4,   2,   0, 220 },  /* near-frozen pulse */
92	  [PARTICLE_STATE_ERROR]     = { 90,   0,   0, 252 },  /* chaotic scatter */
93	};
94	
95	struct particle_s {
96	  int32_t x, y;          /* position, pixels */
97	  int32_t vx, vy;        /* velocity, q8 (256 = 1px/tick) */
98	  uint32_t lcg;          /* per-particle pseudo-noise state */
99	  int32_t last_rx, last_ry;  /* last rendered top-left; skip set_pos if unchanged */
100	};
101	
102	struct pf_state_s {
103	  bool initialized;
104	  bool visible;
105	  enum particle_state state;
106	  lv_obj_t *screen;
107	  lv_obj_t *guide_ring;  /* faint lv_arc, shared motif with pet */
108	  lv_obj_t *core;        /* central pulsing circle */
109	  lv_obj_t *particles[N_PARTICLES];
110	  lv_obj_t *label;
111	  lv_obj_t *status_dot;  /* colored dot paired with the state caption */
112	  lv_obj_t *prev_screen;
113	  struct particle_s p[N_PARTICLES];
114	  lv_timer_t *timer;
115	  uint32_t tick;
116	  /* display geometry (pixels) */
117	  int32_t cx, cy, R, R_sq;
118	};
119	
120	static struct pf_state_s s_pf;
121	
122	/* ---------- LCG (per-particle deterministic pseudo-noise) ---------- */
123	
124	static inline int32_t lcg_next(uint32_t *s)
125	{
126	  *s = (*s * 1103515765u + 12345u) & 0x7fffffffu;
127	  return (int32_t)(*s >> 15) - 16384;   /* [-16384, 16383] */
128	}
129	
130	/* ---------- physics step (runs in LVGL thread via timer) ---------- */
131	
132	static void physics_step(void)
133	{
134	  const phys_t *ph = &s_phys[s_pf.state];
135	  int32_t cx = s_pf.cx, cy = s_pf.cy, R_sq = s_pf.R_sq;
136	  int32_t damp = ph->damp;
137	  int32_t perturb = ph->perturb;
138	  int32_t swirl = ph->swirl;
139	  int32_t radial = ph->radial;
140	
141	  for (int i = 0; i < N_PARTICLES; i++)
142	    {
143	      struct particle_s *p = &s_pf.p[i];
144	      int32_t dx = p->x - cx;
145	      int32_t dy = p->y - cy;
146	
147	      /* LCG noise → small velocity kick (perturb in q8; noise normalized to ~[-1,1] px). */
148	      int32_t nx = lcg_next(&p->lcg);
149	      int32_t ny = lcg_next(&p->lcg);
150	      p->vx += (nx * perturb) / 16384;
151	      p->vy += (ny * perturb) / 16384;
152	
153	      /* Swirl: tangential bias ∝ radial offset (unnormalized → faster swirl
154	       * farther out, reads as rotation). tang = (-dy, dx). */
155	      p->vx += (-dy * swirl) / 64;
156	      p->vy += ( dx * swirl) / 64;
157	
158	      /* Radial bias: outward (+) pulls particles to the rim, inward (-) sucks
159	       * them toward the core. */
160	      p->vx += (dx * radial) / 64;
161	      p->vy += (dy * radial) / 64;
162	
163	      /* Damping. */
164	      p->vx = (p->vx * damp) / 256;
165	      p->vy = (p->vy * damp) / 256;
166	
167	      /* Speed clamp so chaos stays bounded. */
168	      int32_t vmax = 3 * ONE_PX;
169	      if (p->vx >  vmax) p->vx =  vmax;
170	      if (p->vx < -vmax) p->vx = -vmax;
171	      if (p->vy >  vmax) p->vy =  vmax;
172	      if (p->vy < -vmax) p->vy = -vmax;
173	
174	      /* Advance. */
175	      int32_t nxp = p->x + (p->vx >> VEL_Q);
176	      int32_t nyp = p->y + (p->vy >> VEL_Q);
177	
178	      /* Round-bound bounce: if next step leaves the disc, reverse velocity
179	       * (cheap reflection) and don't move this tick. dist_sq in pixel units
180	       * fits in int32 (max ~217k). */
181	      int32_t ddx = nxp - cx;
182	      int32_t ddy = nyp - cy;
183	      int32_t dsq = ddx * ddx + ddy * ddy;
184	      if (dsq > R_sq)
185	        {
186	          p->vx = -p->vx;
187	          p->vy = -p->vy;
188	        }
189	      else
190	        {
191	          p->x = nxp;
192	          p->y = nyp;
193	        }
194	
195	      /* Render — only invalidate when the integer pixel position actually
196	       * changes.  Particles move sub-pixel most ticks (q8 velocity), so an
197	       * unconditional set_pos would invalidate 18 regions every 33 ms even
198	       * when nothing visibly moved.  On flush paths that can't keep up
199	       * (qemu goldfish headless fb) the constant re-invalidation starves the
200	       * flush so the screen never reaches the framebuffer.  Skipping no-op
201	       * moves collapses invalidations to only real pixel crossings. */
202	      lv_obj_t *o = s_pf.particles[i];
203	      if (o)
204	        {
205	          int32_t rx = p->x - (PARTICLE_DIAM / 2);
206	          int32_t ry = p->y - (PARTICLE_DIAM / 2);
207	          if (rx != p->last_rx || ry != p->last_ry)
208	            {
209	              lv_obj_set_pos(o, rx, ry);
210	              p->last_rx = rx;
211	              p->last_ry = ry;
212	            }
213	        }
214	    }
215	
216	  /* Core pulse: opacity breathing driven by tick (no lv_anim to keep the
217	   * pulsing phase-locked to the physics tick). */
218	  if (s_pf.core)
219	    {
220	      uint32_t t = s_pf.tick & 63;            /* 0..63 */
221	      int32_t tri = (t < 32) ? t : (63 - t);  /* triangle 0..31 */
222	      lv_opa_t opa = LV_OPA_60 + (tri * (LV_OPA_COVER - LV_OPA_60)) / 31;
223	      lv_obj_set_style_opa(s_pf.core, opa, 0);
224	    }
225	
226	  s_pf.tick++;
227	}
228	
229	static void timer_cb(lv_timer_t *t)
230	{
231	  (void)t;
232	  if (s_pf.initialized && s_pf.visible)
233	    physics_step();
234	}
235	
236	/* ---------- async apply (runs in LVGL thread) ---------- */
237	
238	static void apply_state_async_cb(void *data)
239	{
240	  enum particle_state st = (enum particle_state)(intptr_t)data;
241	  if (!s_pf.initialized) return;
242	  s_pf.state = st;
243	  uint32_t color = s_state_color[st];
244	
245	  for (int i = 0; i < N_PARTICLES; i++)
246	    {
247	      if (s_pf.particles[i])
248	        {
249	          lv_obj_set_style_bg_color(s_pf.particles[i], lv_color_hex(color), 0);
250	        }
251	    }
252	  if (s_pf.core)
253	    {
254	      lv_obj_set_style_bg_color(s_pf.core, lv_color_hex(color), 0);
255	    }
256	  if (s_pf.label)
257	    {
258	      lv_label_set_text(s_pf.label, s_state_text[st]);
259	    }
260	  if (s_pf.status_dot)
261	    {
262	      lv_obj_set_style_bg_color(s_pf.status_dot, lv_color_hex(color), 0);
263	    }
264	  syslog(LOG_INFO, "[%s] state → %s\n", TAG, s_state_text[st]);
265	}
266	
267	void particle_flow_view_set_state(enum particle_state state)
268	{
269	  if ((int)state < 0 || (int)state > PARTICLE_STATE_ERROR) return;
270	  lv_async_call(apply_state_async_cb, (void *)(intptr_t)state);
271	}
272	
273	/* ---------- screen show / hide ---------- */
274	
275	static void show_async_cb(void *data)
276	{
277	  (void)data;
278	  if (!s_pf.initialized || !s_pf.screen || s_pf.visible) return;
279	  s_pf.prev_screen = lv_screen_active();
280	  lv_screen_load_anim(s_pf.screen, LV_SCR_LOAD_ANIM_FADE_IN,
281	                      SCREEN_FADE_MS, 0, false);
282	  /* lv_screen_load already invalidates the full screen and schedules a redraw;
283	   * the explicit invalidate + lv_refr_now below was a qemu-goldfish-headless
284	   * lazy-flush workaround that is unnecessary on the real CP /dev/lcd0 panel,
285	   * where it caused a full-frame (top-to-bottom) white flicker on every idle
286	   * pet↔particle rotate.  Real hardware renders screen switches fine without
287	   * the extra synchronous refresh, so we drop it to stop the standby flicker. */
288	  s_pf.visible = true;
289	  syslog(LOG_INFO, "[%s] particle screen shown\n", TAG);
290	}
291	
292	void particle_flow_view_show(void)
293	{
294	  if (!s_pf.initialized) return;
295	  lv_async_call(show_async_cb, NULL);
296	}
297	
298	static void hide_async_cb(void *data)
299	{
300	  (void)data;
301	  if (!s_pf.initialized || !s_pf.visible) return;
302	  if (s_pf.prev_screen)
303	    lv_screen_load_anim(s_pf.prev_screen, LV_SCR_LOAD_ANIM_FADE_IN,
304	                        SCREEN_FADE_MS, 0, false);
305	  s_pf.visible = false;
306	  syslog(LOG_INFO, "[%s] particle screen hidden\n", TAG);
307	}
308	
309	void particle_flow_view_hide(void)
310	{
311	  if (!s_pf.initialized) return;
312	  lv_async_call(hide_async_cb, NULL);
313	}
314	
315	bool particle_flow_view_is_visible(void)
316	{
317	  return s_pf.visible;
318	}
319	
320	/* ---------- init ---------- */
321	
322	static lv_obj_t *make_circle(lv_obj_t *parent, int32_t diam,
323	                              uint32_t color, lv_opa_t opa)
324	{
325	  lv_obj_t *o = lv_obj_create(parent);
326	  if (!o) return NULL;
327	  lv_obj_remove_style_all(o);
328	  lv_obj_set_size(o, diam, diam);
329	  lv_obj_set_style_radius(o, LV_RADIUS_CIRCLE, 0);
330	  lv_obj_set_style_bg_color(o, lv_color_hex(color), 0);
331	  lv_obj_set_style_bg_opa(o, opa, 0);
332	  lv_obj_set_style_border_width(o, 0, 0);
333	  lv_obj_center(o);
334	  return o;
335	}
336	
337	int particle_flow_view_init(void)
338	{
339	  if (s_pf.initialized) return 0;
340	
341	  memset(&s_pf, 0, sizeof(s_pf));
342	  s_pf.state = PARTICLE_STATE_IDLE;
343	
344	  s_pf.screen = lv_obj_create(NULL);
345	  if (!s_pf.screen) return -ENOMEM;
346	  lv_obj_set_style_bg_color(s_pf.screen, lv_color_hex(UI_PAL_BG), 0);
347	  lv_obj_set_style_bg_opa(s_pf.screen, LV_OPA_COVER, 0);
348	  lv_obj_set_style_text_font(s_pf.screen, &lv_font_misans_16_cjk, 0);
349	
350	  /* Display geometry: center + round bound. */
351	  lv_display_t *disp = lv_display_get_default();
352	  int32_t h = lv_display_get_horizontal_resolution(disp);
353	  int32_t v = lv_display_get_vertical_resolution(disp);
354	  s_pf.cx = h / 2;
355	  s_pf.cy = v / 2;
356	  int32_t half = (h < v ? h : v) / 2;
357	  /* Inscribe the particle travel bound INSIDE the round face: subtract the
358	   * particle radius (PARTICLE_DIAM/2) so a particle centred at the bound has
359	   * its outer edge on the circle, never spilling into the bezel. */
360	  s_pf.R = (half > 8) ? (half - 8 - PARTICLE_DIAM / 2) : 8;
361	  s_pf.R_sq = s_pf.R * s_pf.R;
362	
363	  /* Faint guide ring (shared motif with pet_status_view): a barely-there dark
364	   * boundary circle.  The particles + core already carry the state color, so
365	   * the ring itself stays subtle rather than competing with them. */
366	  s_pf.guide_ring = lv_arc_create(s_pf.screen);
367	  if (s_pf.guide_ring)
368	    {
369	      lv_obj_set_size(s_pf.guide_ring, GUIDE_RING_DIAM, GUIDE_RING_DIAM);
370	      lv_obj_center(s_pf.guide_ring);
371	      lv_arc_set_bg_angles(s_pf.guide_ring, 0, 360);
372	      lv_arc_set_angles(s_pf.guide_ring, 0, 360);
373	      lv_obj_set_style_arc_width(s_pf.guide_ring, 2, LV_PART_MAIN);
374	      lv_obj_set_style_arc_width(s_pf.guide_ring, 0, LV_PART_INDICATOR);
375	      lv_obj_set_style_arc_color(s_pf.guide_ring, lv_color_hex(UI_PAL_TRACK), LV_PART_MAIN);
376	      lv_obj_set_style_bg_opa(s_pf.guide_ring, LV_OPA_TRANSP, LV_PART_KNOB);
377	      lv_obj_remove_flag(s_pf.guide_ring, LV_OBJ_FLAG_CLICKABLE);
378	    }
379	
380	  /* Central pulsing core. */
381	  s_pf.core = make_circle(s_pf.screen, CORE_DIAM, UI_PAL_IDLE, LV_OPA_80);
382	
383	  /* Particles — scattered initially within the disc. */
384	  uint32_t seed = 0x1234abcd;
385	  for (int i = 0; i < N_PARTICLES; i++)
386	    {
387	      /* place around a ring with jitter so they don't overlap the core */
388	      int32_t ang = (i * 360 / N_PARTICLES) % 360;
389	      /* cheap sin/cos via a 4-bin triangle so no math.h: */
390	      int32_t qx = (ang < 90) ? ang : (ang < 270) ? (180 - ang) : (ang - 360);
391	      int32_t qy = ((ang + 270) % 360);
392	      qy = (qy < 90) ? qy : (qy < 270) ? (180 - qy) : (qy - 360);
393	      /* qx, qy ∈ [-90, 90] → normalize to [-1, 1] */
394	      int32_t rx = (qx * 0x7fff) / 90;
395	      int32_t ry = (qy * 0x7fff) / 90;
396	      int32_t radius = s_pf.R * 2 / 3;
397	      int32_t jitter = (lcg_next(&seed) * radius) / 16384;
398	      int32_t rr = radius + (jitter / 4);
399	      if (rr < 6) rr = 6;
400	      if (rr > s_pf.R - 2) rr = s_pf.R - 2;
401	
402	      s_pf.p[i].x = s_pf.cx + (int32_t)(((int64_t)rx * rr) / 0x7fff);
403	      s_pf.p[i].y = s_pf.cy + (int32_t)(((int64_t)ry * rr) / 0x7fff);
404	      s_pf.p[i].vx = lcg_next(&seed) / 8;   /* small initial velocity */
405	      s_pf.p[i].vy = lcg_next(&seed) / 8;
406	      s_pf.p[i].lcg = seed;
407	
408	      /* Soft particles — 80% opacity recedes them into the near-black field
409	       * (HachimoDock softness) instead of hard neon dots. */
410	      s_pf.particles[i] = make_circle(s_pf.screen, PARTICLE_DIAM,
411	                                       UI_PAL_IDLE, LV_OPA_80);
412	      if (s_pf.particles[i])
413	        {
414	          int32_t prx = s_pf.p[i].x - (PARTICLE_DIAM / 2);
415	          int32_t pry = s_pf.p[i].y - (PARTICLE_DIAM / 2);
416	          lv_obj_set_pos(s_pf.particles[i], prx, pry);
417	          s_pf.p[i].last_rx = prx;
418	          s_pf.p[i].last_ry = pry;
419	        }
420	    }
421	
422	  /* State caption row (dot + text), mirroring pet_status_view's caption so the
423	   * particle page's status text is anchored to a UI block rather than floating
424	   * as a bare label.  Placed low inside the circle, clear of the core/ring. */
425	  {
426	    lv_obj_t *caption = lv_obj_create(s_pf.screen);
427	    if (caption)
428	      {
429	        lv_obj_remove_flag(caption, LV_OBJ_FLAG_SCROLLABLE);
430	        lv_obj_set_size(caption, LV_SIZE_CONTENT, LV_SIZE_CONTENT);
431	        lv_obj_set_style_bg_opa(caption, LV_OPA_TRANSP, 0);
432	        lv_obj_set_style_border_width(caption, 0, 0);
433	        lv_obj_set_style_pad_all(caption, 0, 0);
434	        lv_obj_set_flex_flow(caption, LV_FLEX_FLOW_ROW);
435	        lv_obj_set_flex_align(caption, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER,
436	                              LV_FLEX_ALIGN_CENTER);
437	        lv_obj_set_style_pad_column(caption, 6, 0);
438	        /* 88 matches pet_status_view's PET_LABEL_DY: the caption (dot+text)
439	         * is 20px tall (MiSans line_height=20), so its top is 88-10=78 below
440	         * center → y=226, clearing the 150px guide ring bottom (y=223) by 3px
441	         * instead of overlapping. */
442	        lv_obj_align(caption, LV_ALIGN_CENTER, 0, 88);
443	
444	        s_pf.status_dot = lv_obj_create(caption);
445	        if (s_pf.status_dot)
446	          {
447	            lv_obj_remove_flag(s_pf.status_dot, LV_OBJ_FLAG_SCROLLABLE);
448	            lv_obj_set_size(s_pf.status_dot, 8, 8);
449	            lv_obj_set_style_radius(s_pf.status_dot, LV_RADIUS_CIRCLE, 0);
450	            lv_obj_set_style_bg_color(s_pf.status_dot, lv_color_hex(UI_PAL_IDLE), 0);
451	            lv_obj_set_style_bg_opa(s_pf.status_dot, LV_OPA_COVER, 0);
452	            lv_obj_set_style_border_width(s_pf.status_dot, 0, 0);
453	            lv_obj_set_style_pad_all(s_pf.status_dot, 0, 0);
454	          }
455	
456	        s_pf.label = lv_label_create(caption);
457	        if (s_pf.label)
458	          {
459	            lv_label_set_text(s_pf.label, s_state_text[PARTICLE_STATE_IDLE]);
