17	/*
18	 * standby_view.c — 待机界面（暗色数字时钟）。
19	 *
20	 * 长时间无操作后(由 lvgl_ui_channel.c 的 60s 空闲计时器触发),主界面渐隐渐显
21	 * 切到这块极简的暗色数字时钟:大号 HH:MM(Montserrat 24) + 小号日期(月/日/周,
22	 * MiSans 16 CJK) + "待机中"提示。整屏比宠物/粒子页更暗更静,一眼可辨是"睡了"。
23	 * 任意真实交互(lvgl_ui_channel 的任一公共入口)都会调 standby_view_hide() 渐隐
24	 * 渐显回先前页面。时钟由 1s 定时器在 LVGL 线程刷新。
25	 *
26	 * 字体:HH:MM 用内置 Montserrat 24(纯 ASCII 数字/冒号),日期与提示用 app 自带
27	 * MiSans 16 CJK(AP 上为 3755 字全量静态字体,月/日/周/一二三…六均在)。
28	 */
29	
30	#include <nuttx/config.h>
31	
32	#ifdef CONFIG_AI_AGENT_STANDBY_UI
33	
34	#include "ui/standby_view.h"
35	#include "ui/ui_palette.h"
36	
37	#include <stddef.h>
38	#include <stdbool.h>
39	#include <stdint.h>
40	#include <string.h>
41	#include <stdio.h>
42	#include <time.h>
43	#include <syslog.h>
44	#include <errno.h>
