308	    if (!s_state.initialized || !s_state.screen_visible) return;
309	    /* A pending remote permission request owns the foreground: never yield it
310	     * back to the pet home screen while the approval page is up, or the user
311	     * loses the S2/S3 approve/cancel cue mid-decision. */
312	    if (s_state.approval_visible) return;
313	    if (!pet_status_view_is_visible() &&
314	        (lv_tick_get() - s_pet_last_msg_tick) >= PET_IDLE_YIELD_MS)
315	      {
316	        /* Yield: the chat screen stays alive but releases the foreground so
317	         * the pet home screen shows.  Clearing screen_visible lets the next
318	         * incoming message re-take the foreground via lvgl_ui_channel_show. */
319	        s_state.screen_visible = false;
320	        pet_status_view_show();
321	        syslog(LOG_INFO, "[%s] idle → pet home screen\n", TAG);
322	      }
