337	 * the foreground between the pet home screen and the particle flow every
338	 * ROTATE_INTERVAL_MS so a demo shows both round-screen pages without a
339	 * manual set_page.  Any non-idle state or incoming chat message pauses
340	 * rotation (reset the tick), since those have their own pet animation or
341	 * preempt the foreground.  Mirrors UI方案.md §2.4 "agent 空闲态自动切". */
342	#define ROTATE_INTERVAL_MS  10000
343	static lv_timer_t *s_rotate_timer = NULL;
344	static uint32_t    s_rotate_last_switch_tick = 0;
345	static int         s_last_pet_state = 0;   /* mirrored in set_pet_state */
346	
