353	{
354	    (void)t;
355	    if (!s_state.initialized) return;
356	    if (s_state.screen_visible) return;        /* chat holds the foreground */
357	    if (s_state.approval_visible) return;      /* approval page holds it */
358	    if (s_last_pet_state != 0) return;         /* only idle rotates */
359	#ifdef CONFIG_AI_AGENT_STANDBY_UI
360	    if (standby_view_is_visible()) return;     /* standby clock holds it */
361	#endif
362	    uint32_t now = lv_tick_get();
363	    if ((now - s_rotate_last_switch_tick) < ROTATE_INTERVAL_MS) return;
364	    /* Switch the views directly (not set_page) so idle rotation never counts
365	     * as user activity and cannot postpone the standby clock. */
366	    if (pet_status_view_is_visible())
367	      {
368	        pet_status_view_hide();
369	        particle_flow_view_show();
370	        syslog(LOG_INFO, "[%s] idle rotate → particle\n", TAG);
371	      }
372	    else if (particle_flow_view_is_visible())
373	      {
374	        particle_flow_view_hide();
375	        pet_status_view_show();
376	        syslog(LOG_INFO, "[%s] idle rotate → pet\n", TAG);
377	      }
378	    s_rotate_last_switch_tick = now;
379	}
