412	     * executing / waiting animation is never interrupted mid-task. */
413	    if (s_last_pet_state != 0)
414	      {
415	        s_last_activity_tick = lv_tick_get();
416	        return;
417	      }
418	    if ((lv_tick_get() - s_last_activity_tick) >= STANDBY_TIMEOUT_MS)
419	      {
