17	/*
18	 * standby_view.c — 待机界面（暗色数字时钟）。
19	 *
20	 * 长时间无操作后(由 lvgl_ui_channel.c 的 60s 空闲计时器触发),主界面渐隐渐显
21	 * 切到这块极简的暗色数字时钟:大号 HH:MM(Montserrat 24) + 小号日期(月/日/周,
22	 * MiSans 16 CJK) + "待机中"提示。整屏比宠物/粒子页更暗更静,一眼可辨是"睡了"。
23	 * 任意真实交互(lvgl_ui_channel 的任一公共入口)都会调 standby_view_hide() 渐隐
24	 * 渐显回先前页面。时钟由 1s 定时器在 LVGL 线程刷新。
25	 *
26	 * 字体:HH:MM 用内置 Montserrat 24(纯 ASCII 数字/冒号),日期与提示用 app 自带
27	 * MiSans 16 CJK(AP 上为 3755 字全量静态字体,月/日/周/一二三…六均在)。
28	 */
29	
30	#include <nuttx/config.h>
31	
32	#ifdef CONFIG_AI_AGENT_STANDBY_UI
33	
34	#include "ui/standby_view.h"
35	#include "ui/ui_palette.h"
36	
37	#include <stddef.h>
38	#include <stdbool.h>
39	#include <stdint.h>
40	#include <string.h>
41	#include <stdio.h>
42	#include <time.h>
43	#include <syslog.h>
44	#include <errno.h>
45	
46	#include <lvgl/lvgl.h>
47	
48	#define TAG "standby_view"
49	
50	/* 屏幕切换淡入时长(ms)。与 pet/particle 一致:用淡入交叉渐变代替硬切换,把
51	 * 整帧 SPI flush 的刷屏分散到多帧,呈现为优雅的渐隐渐显。 */
52	#define SCREEN_FADE_MS 500
53	
54	LV_FONT_DECLARE(lv_font_misans_16_cjk);
55	
56	static const char *const s_wday_cn[] = {
57	  "周日", "周一", "周二", "周三", "周四", "周五", "周六",
58	};
59	
60	struct standby_state_s {
61	  bool initialized;
62	  bool visible;
63	  lv_obj_t *screen;
64	  lv_obj_t *clock;   /* HH:MM — Montserrat 24 */
65	  lv_obj_t *date;    /* M月D日 周X — MiSans 16 CJK */
66	  lv_obj_t *hint;    /* 待机中 — MiSans 16 CJK */
67	  lv_obj_t *prev_screen;
68	  lv_timer_t *timer; /* 1s clock refresh */
69	};
70	
71	static struct standby_state_s s_sb;
72	
73	static void refresh_time(void)
74	{
75	  if (!s_sb.initialized) return;
76	
77	  time_t now = time(NULL);
78	  struct tm tm;
79	  localtime_r(&now, &tm);
80	
81	  if (s_sb.clock)
82	    {
83	      char buf[16];
84	      snprintf(buf, sizeof(buf), "%02d:%02d", tm.tm_hour, tm.tm_min);
85	      lv_label_set_text(s_sb.clock, buf);
86	    }
87	  if (s_sb.date)
88	    {
89	      char buf[32];
90	      snprintf(buf, sizeof(buf), "%d月%d日 %s",
91	               tm.tm_mon + 1, tm.tm_mday, s_wday_cn[tm.tm_wday % 7]);
92	      lv_label_set_text(s_sb.date, buf);
93	    }
94	}
95	
96	static void timer_cb(lv_timer_t *t)
97	{
98	  (void)t;
99	  if (s_sb.initialized && s_sb.visible)
100	    refresh_time();
101	}
102	
103	/* ---------- screen show / hide (async, runs in LVGL thread) ---------- */
104	
105	static void show_async_cb(void *data)
106	{
107	  (void)data;
108	  if (!s_sb.initialized || !s_sb.screen || s_sb.visible) return;
109	  s_sb.prev_screen = lv_screen_active();
110	  refresh_time();
111	  lv_screen_load_anim(s_sb.screen, LV_SCR_LOAD_ANIM_FADE_IN,
112	                      SCREEN_FADE_MS, 0, false);
113	  s_sb.visible = true;
114	  syslog(LOG_INFO, "[%s] standby clock shown\n", TAG);
115	}
116	
117	void standby_view_show(void)
118	{
119	  if (!s_sb.initialized) return;
120	  lv_async_call(show_async_cb, NULL);
121	}
122	
123	static void hide_async_cb(void *data)
124	{
125	  (void)data;
126	  if (!s_sb.initialized || !s_sb.visible) return;
127	  if (s_sb.prev_screen)
128	    lv_screen_load_anim(s_sb.prev_screen, LV_SCR_LOAD_ANIM_FADE_IN,
129	                        SCREEN_FADE_MS, 0, false);
130	  s_sb.visible = false;
131	  syslog(LOG_INFO, "[%s] standby clock hidden\n", TAG);
132	}
133	
134	void standby_view_hide(void)
135	{
136	  if (!s_sb.initialized) return;
137	  lv_async_call(hide_async_cb, NULL);
138	}
139	
140	bool standby_view_is_visible(void)
141	{
142	  return s_sb.visible;
143	}
144	
145	/* ---------- init ---------- */
146	
147	int standby_view_init(void)
148	{
149	  if (s_sb.initialized) return 0;
150	
151	  memset(&s_sb, 0, sizeof(s_sb));
152	
153	  s_sb.screen = lv_obj_create(NULL);
154	  if (!s_sb.screen) return -ENOMEM;
155	  lv_obj_set_style_bg_color(s_sb.screen, lv_color_hex(UI_PAL_BG), 0);
156	  lv_obj_set_style_bg_opa(s_sb.screen, LV_OPA_COVER, 0);
157	
158	  /* 居中一列:大号 HH:MM 在上、日期在中、"待机中"提示在下。整体偏暗。 */
159	  lv_obj_t *col = lv_obj_create(s_sb.screen);
160	  if (!col) goto fail;
161	  lv_obj_remove_flag(col, LV_OBJ_FLAG_SCROLLABLE);
162	  lv_obj_set_size(col, LV_SIZE_CONTENT, LV_SIZE_CONTENT);
163	  lv_obj_set_style_bg_opa(col, LV_OPA_TRANSP, 0);
164	  lv_obj_set_style_border_width(col, 0, 0);
165	  lv_obj_set_style_pad_all(col, 0, 0);
166	  lv_obj_set_flex_flow(col, LV_FLEX_FLOW_COLUMN);
167	  lv_obj_set_flex_align(col, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER,
168	                        LV_FLEX_ALIGN_CENTER);
169	  lv_obj_set_style_pad_row(col, 14, 0);
170	  lv_obj_center(col);
171	
172	  s_sb.clock = lv_label_create(col);
173	  if (!s_sb.clock) goto fail;
174	  lv_label_set_text(s_sb.clock, "--:--");
175	  lv_obj_set_style_text_font(s_sb.clock, &lv_font_montserrat_24, 0);
176	  lv_obj_set_style_text_color(s_sb.clock, lv_color_hex(UI_PAL_IDLE), 0);
177	
178	  s_sb.date = lv_label_create(col);
179	  if (!s_sb.date) goto fail;
180	  lv_label_set_text(s_sb.date, "待机中");
181	  lv_obj_set_style_text_font(s_sb.date, &lv_font_misans_16_cjk, 0);
182	  lv_obj_set_style_text_color(s_sb.date, lv_color_hex(UI_PAL_MUTED), 0);
183	
184	  s_sb.hint = lv_label_create(col);
185	  if (!s_sb.hint) goto fail;
186	  lv_label_set_text(s_sb.hint, "待机中");
187	  lv_obj_set_style_text_font(s_sb.hint, &lv_font_misans_16_cjk, 0);
188	  lv_obj_set_style_text_color(s_sb.hint, lv_color_hex(UI_PAL_MUTED), 0);
189	
190	  s_sb.timer = lv_timer_create(timer_cb, 1000, NULL);
191	  if (s_sb.timer)
192	    lv_timer_set_repeat_count(s_sb.timer, -1);
193	
194	  s_sb.initialized = true;
195	  syslog(LOG_INFO, "[%s] init OK (暗色数字时钟)\n", TAG);
196	  return 0;
197	
198	fail:
199	  if (s_sb.screen) lv_obj_del(s_sb.screen);
200	  memset(&s_sb, 0, sizeof(s_sb));
201	  return -ENOMEM;
202	}
203	
204	#endif /* CONFIG_AI_AGENT_STANDBY_UI */
